"use strict";
// Export only Legacy's runtime and referenced media. No dependencies or game-code imports.
const fs = require("node:fs");
const path = require("node:path");
const crypto = require("node:crypto");
const { compile } = require("./compile.cjs");

const ROOT = path.resolve(__dirname, "..");
const DEFAULT_OUT = path.join(ROOT, "dist");
const MARKER = ".legacy-build.json";
const hash = (data) => crypto.createHash("sha256").update(data).digest("hex");
const within = (parent, child) => {
  const rel = path.relative(parent, child);
  return (
    !rel ||
    (!rel.startsWith(".." + path.sep) && rel !== ".." && !path.isAbsolute(rel))
  );
};

function options(args) {
  const out = { out: DEFAULT_OUT, assetsRoot: path.resolve(ROOT, "..") };
  for (let i = 0; i < args.length; i++) {
    const key = { "--out": "out", "--assets-root": "assetsRoot" }[args[i]];
    if (!key || !args[i + 1] || args[i + 1].startsWith("--"))
      throw new Error(
        "Usage: node tools/build.cjs [--out DIR] [--assets-root DIR]",
      );
    out[key] = path.resolve(args[++i]);
  }
  return out;
}

function walk(root, rel = "") {
  const result = [];
  for (const entry of fs.readdirSync(path.join(root, rel), {
    withFileTypes: true,
  })) {
    const file = path.posix.join(rel, entry.name);
    if (entry.isSymbolicLink())
      throw new Error(
        "Refusing to replace output containing a symlink: " + file,
      );
    if (entry.isDirectory()) result.push(...walk(root, file));
    else if (entry.isFile()) result.push(file);
    else throw new Error("Unexpected output entry: " + file);
  }
  return result.sort();
}

function checkExisting(out) {
  if (!fs.existsSync(out)) return;
  if (fs.lstatSync(out).isSymbolicLink())
    throw new Error("Output must not be a symlink");
  const marker = path.join(out, MARKER);
  if (!fs.existsSync(marker))
    throw new Error(
      "Refusing to overwrite a directory not generated by this builder: " + out,
    );
  const previous = JSON.parse(fs.readFileSync(marker, "utf8"));
  if (
    previous.kind !== "legacy-standalone" ||
    previous.version !== 1 ||
    !previous.files
  )
    throw new Error("Unknown build manifest");
  const files = walk(out).filter((file) => file !== MARKER);
  if (
    JSON.stringify(files) !== JSON.stringify(Object.keys(previous.files).sort())
  )
    throw new Error(
      "Output has added or removed files; preserve those changes before rebuilding",
    );
  for (const file of files)
    if (hash(fs.readFileSync(path.join(out, file))) !== previous.files[file])
      throw new Error(
        "Output was edited; preserve changes before rebuilding: " + file,
      );
}

function build({ out, assetsRoot }) {
  out = path.resolve(out);
  assetsRoot = fs.realpathSync(assetsRoot);
  // Do not allow replacing source, its ancestors, or another directory inside this repo.
  const repo = path.resolve(ROOT, "..");
  if (within(out, ROOT) || (within(repo, out) && out !== DEFAULT_OUT))
    throw new Error(
      "Use legacy/dist or a separate export directory outside this repository",
    );
  fs.mkdirSync(path.dirname(out), { recursive: true });
  if (path.join(fs.realpathSync(path.dirname(out)), path.basename(out)) !== out)
    throw new Error("Output parent must not contain symlinks");
  checkExisting(out);

  const peerPackage = path.join(ROOT, "node_modules/peerjs");
  fs.mkdirSync(path.join(ROOT, "vendor"), { recursive: true });
  fs.writeFileSync(
    path.join(ROOT, "vendor/peerjs.min.js"),
    fs
      .readFileSync(path.join(peerPackage, "dist/peerjs.min.js"), "utf8")
      .replace(/\n\/\/# sourceMappingURL=.*(?:\n|$)/, "\n"),
  );
  fs.copyFileSync(
    path.join(peerPackage, "LICENSE"),
    path.join(ROOT, "vendor/PEERJS-LICENSE.txt"),
  );

  const output = new Map(Object.entries(compile()));
  const localMedia = (text) =>
    text
      .replace(/\.\.\/(img|sound)\//g, "$1/")
      .replace(/\.\.\/favicon\.ico/g, "favicon.ico");
  const html = fs.readFileSync(path.join(ROOT, "index.html"), "utf8");
  output.set("index.html", Buffer.from(localMedia(html)));
  output.set("coach.html", fs.readFileSync(path.join(ROOT, "coach.html")));
  const resources = [
    "manifest.webmanifest",
    "vendor/PEERJS-LICENSE.txt",
    ...[
      "css",
      "js",
      "engine",
      "content",
      "controllers",
      "client",
      "offline",
      "protocol",
      "vendor",
    ].flatMap((dir) =>
      walk(path.join(ROOT, dir))
        .filter((file) => /\.(?:js|mjs|css)$/.test(file))
        .map((file) => dir + "/" + file),
    ),
  ];
  const media = new Set(["sound/NGUON.txt", "img/icon.svg"]);
  for (const file of resources) {
    if (!within(ROOT, path.resolve(ROOT, file)))
      throw new Error("Runtime resource escapes Legacy: " + file);
    let content = fs.readFileSync(path.join(ROOT, file), "utf8");
    for (const match of content.matchAll(
      /['"]\.\.\/((?:img|sound)\/[^'"]+)['"]/g,
    )) {
      if (!match[1].endsWith("/")) media.add(match[1]);
    }
    if (file === "js/01b-audio.js") {
      for (const match of content.matchAll(
        /['"]((?:sfx|ui|voice|music)\/[^'"]+\.mp3)['"]/g,
      ))
        media.add("sound/" + match[1]);
    }
    content = localMedia(content);
    output.set(file, Buffer.from(content));
  }
  // Favicon requests are made automatically by browsers, even without a link element.
  media.add("favicon.ico");
  for (const file of [...media].sort()) {
    const source = fs.realpathSync(path.resolve(assetsRoot, file));
    if (!within(assetsRoot, source))
      throw new Error("Media escapes assets root: " + file);
    output.set(file, fs.readFileSync(source));
  }
  output.set(
    "README.txt",
    Buffer.from(
      "Legacy Arena\nServe locally: python3 -m http.server 8001 --bind 127.0.0.1\nOffline mode uses the local engine. Online rooms require the included project server, not a static host alone.\nOld coach mode: coach.html\nAudio attribution: sound/NGUON.txt\n",
    ),
  );
  const workerTemplate = fs.readFileSync(
    path.join(ROOT, "tools/service-worker.js"),
    "utf8",
  );
  const contentVersion = hash(
    Buffer.concat([...output.values(), Buffer.from(workerTemplate)]),
  );
  output.set(
    "sw.js",
    Buffer.from(
      workerTemplate.replace("__CACHE_VERSION__", contentVersion.slice(0, 16)),
    ),
  );
  const precache = [...output.keys()].filter(
    (file) => !file.endsWith(".mp3") && file !== "sw.js",
  );
  output.set("precache.json", Buffer.from(JSON.stringify(precache)));
  const files = Object.fromEntries(
    [...output]
      .sort(([a], [b]) => a.localeCompare(b))
      .map(([file, data]) => [file, hash(data)]),
  );
  const staging = fs.mkdtempSync(
    path.join(path.dirname(out), ".legacy-build-"),
  );
  const backup = staging + ".previous";
  try {
    for (const [file, data] of output) {
      const destination = path.join(staging, file);
      fs.mkdirSync(path.dirname(destination), { recursive: true });
      fs.writeFileSync(destination, data);
    }
    fs.writeFileSync(
      path.join(staging, MARKER),
      JSON.stringify(
        { kind: "legacy-standalone", version: 1, files },
        null,
        2,
      ) + "\n",
    );
    if (fs.existsSync(out)) fs.renameSync(out, backup);
    try {
      fs.renameSync(staging, out);
    } catch (error) {
      if (fs.existsSync(backup)) fs.renameSync(backup, out);
      throw error;
    }
    if (fs.existsSync(backup)) fs.rmSync(backup, { recursive: true });
  } finally {
    if (fs.existsSync(staging)) fs.rmSync(staging, { recursive: true });
  }
  // GitHub Pages serves tracked source files directly, without running Node.
  // Ship the generated modules and a source-specific offline cache alongside it.
  // Media stays shared in ../img and ../sound instead of duplicating it in Git.
  // An external --assets-root only supplies the standalone export; it cannot
  // populate the ../img paths of a source deployment.
  if (assetsRoot === fs.realpathSync(repo)) {
    const sourcePaths = precache
      .filter((file) => file !== "README.txt")
      .map((file) => (media.has(file) ? "../" + file : file))
      .sort();
    const sourceVersion = hash(
      Buffer.from(
        JSON.stringify([
          hash(workerTemplate),
          ...sourcePaths.map((file) => [
            file,
            hash(fs.readFileSync(path.resolve(ROOT, file))),
          ]),
        ]),
      ),
    );
    fs.writeFileSync(
      path.join(ROOT, "precache.json"),
      JSON.stringify(sourcePaths, null, 2) + "\n",
    );
    fs.writeFileSync(
      path.join(ROOT, "sw.js"),
      workerTemplate.replace("__CACHE_VERSION__", sourceVersion.slice(0, 16)),
    );
  }
  const bytes = [...output.values()].reduce(
    (sum, data) => sum + data.length,
    0,
  );
  console.log(
    `Legacy standalone: ${output.size} files, ${(bytes / 1048576).toFixed(1)} MiB -> ${out}`,
  );
  return { files, out };
}

if (require.main === module) {
  try {
    build(options(process.argv.slice(2)));
  } catch (error) {
    console.error(error.message);
    process.exitCode = 1;
  }
}
module.exports = { build, ROOT, DEFAULT_OUT, MARKER };
